```sql
SELECT p.poi_name
FROM pois p
ORDER BY p.geometry <-> (
  SELECT geometry FROM pois WHERE poi_name ILIKE '%School 31 Luxury Lofts%' AND addr_city ILIKE '%Rochester%' AND addr_state ILIKE '%NY%' LIMIT 1
) - (
  SELECT geometry FROM pois WHERE poi_name ILIKE '%Shop One%' AND addr_city ILIKE '%Rochester%' AND addr_state ILIKE '%NY%' LIMIT 1
)
LIMIT 1;
```

```sql
SELECT pois.poi_name
FROM pois
ORDER BY pois.geometry <-> (
  SELECT ST_MakePoint(-106.6466, 35.0844) -- Approximate point near ABQ BioPark
) * (
  CASE WHEN pois.amenity = 'restaurant' THEN 1 ELSE 1000000 END
)
LIMIT 1;
```
